 "content": "from collections import deque


def transform(grid):
    """Reverse the color order of each separate nonzero nested panel."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            palette = set()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                palette.add(grid[y][x])
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            colors = sorted(palette, key=lambda color: -sum(
                1 for y, x in cells if grid[y][x] == color
            ))
            # Layer size is represented by the area of that color's bounding box.
            colors.sort(key=lambda color: -_bbox_area(grid, cells, color))
            reverse = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = reverse[grid[y][x]]
    return out


def _bbox_area(grid, cells, color):
    points = [(y, x) for y, x in cells if grid[y][x] == color]
    return (max(y for y, _ in points) - min(y for y, _ in points) + 1) * (
        max(x for _, x in points) - min(x for _, x in points) + 1
    )


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
